//! Authority-supplied epoch roots: the protected key path.
//!
//! A protected publisher must NOT draw its own epoch root. The root for a
//! `(org, version, publisher, server generation, epoch)` scope is generated by
//! the authority with a CSPRNG, stored once, and returned unchanged on every
//! retry of that scope — otherwise the same identity would publish under two
//! different keys (equivocation) and a receiver holding the first root could not
//! open the second epoch's objects.
//!
//! This module is the seam: a transport-agnostic [`AuthorityRootProvider`] the
//! embedding runtime implements (TLS to the authority, or an in-process trusted
//! component), the typed [`AuthorityEpochRoot`] it returns, and the
//! [`AuthorityRootGuard`] that makes the runtime's own decisions monotonic.
//! This guard is per-process and the nonce journal is per-host: neither grants
//! a multi-host publisher lease. The authority MUST lease one publisher identity
//! to exactly one host and fence the old host before failover; failover needs a
//! new authoritative generation and fresh root (see `PROTOCOL.md`).
//! There is no HTTP client or multi-host lease *transport* here; no route is
//! guessed. The [`LeaseFence`] seam is the local half: an exclusive-lease client
//! (see `authority_http`) implements it, and a guarded publisher refuses to seal
//! without a permit.
use crate::{Error, Result, Secret};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::sync::Arc;

/// A cheap, scope-bound, local-only lease observation.
///
/// It is deliberately not enough to encrypt on its own: the embedding runtime
/// must consult it through the fence it handed to the [`Publisher`]
/// (crate::Publisher) or to an [`AuthorityRootGuard`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LeasePermit {
    /// A local, monotonic deadline (same clock domain as the fence's own
    /// monotonic source, not a wall-clock Unix ms timestamp) after which sealing
    /// must stop. It is conservatively derived from the server expiry and clock
    /// uncertainty, never from the server value alone.
    pub until_monotonic_ms: u64,
}

/// The exclusive-lease fence: shared evidence that this process still owns the
/// publisher identity's lease.
///
/// The authority (not this crate) leases one publisher identity to exactly one
/// host; `AuthorityRootGuard` is per-process and `DurableCounterJournal` is
/// single-host, so neither prevents two hosts from reserving the same nonce
/// counter. A protected runtime therefore consults a fence before every seal:
///
/// * `permit(now_ms)` must return **without any I/O and without blocking** on a
///   data-plane path (it is called once per seal);
/// * it must return [`None`] once the lease expired, was revoked/released, or a
///   renewal failed — a lost lease fails closed and is never resumed by a retry
///   that mutates ownership;
/// * the returned permit must be *conservative*: derived from the server expiry
///   minus clock uncertainty, never later than the server actually honours;
/// * it must not grant a permit before the server's `notBeforeMs` has elapsed
///   (a new root must not encrypt before the previous epoch's tail ended).
pub trait LeaseFence: Send + Sync {
    /// A permit while the lease is locally believed valid, else [`None`].
    fn permit(&self, now_ms: u64) -> Option<LeasePermit>;
}

/// Where a [`Publisher`](crate::Publisher)'s epoch root came from.
///
/// Reported so a caller can assert the protected path was taken. It is never
/// encoded on the wire and does not change MC02/MG02 bytes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum KeySource {
    /// The root was drawn locally by [`Publisher::new`](crate::Publisher::new).
    /// Test fixtures and explicit local operation only; never protected
    /// delivery.
    LocalTestOnly,
    /// The root came from an authenticated [`AuthorityRootProvider`].
    Authority,
}

/// The durable counter scope a publisher is bound to:
/// `(version, publisher, epoch, publisher_generation)`.
///
/// Two publishers with the same scope share one counter sequence, which is what
/// makes a same-root retry continue instead of restart. A different generation
/// or epoch is a different scope, and therefore a different nonce space.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CounterScope {
    /// Media version identity.
    pub version: [u8; 16],
    /// Publisher instance identity.
    pub publisher: [u8; 16],
    /// The epoch.
    pub epoch: u64,
    /// The generation that goes on the wire as `publisher_generation`.
    pub generation: u32,
}

/// The identity an epoch root is requested for, plus the epoch the caller
/// believes is current.
///
/// The server generation is deliberately ABSENT: it is assigned by the
/// authority and read back from [`AuthorityEpochRoot`], never supplied by the
/// caller.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EpochRootRequest {
    /// Owning organization.
    pub org: [u8; 16],
    /// Media version identity (the MC02/MG02 `version` field).
    pub version: [u8; 16],
    /// Feed identity (the MC02/MG02 `feed` field).
    pub feed: [u8; 16],
    /// Publisher machine identity (the authority's create-once scope).
    pub publisher_machine: [u8; 16],
    /// Publisher instance identity (the MC02/MG02 `publisher` field).
    pub publisher: [u8; 16],
    /// The epoch being requested: the caller asks for the CURRENT epoch and must
    /// never prefetch a future one.
    pub epoch: u64,
    /// The caller's current time, for the authority's own expiry bookkeeping.
    pub now_ms: u64,
}

/// One authority-issued epoch root and the context it is valid in.
///
/// Holds secret key material. `Debug` is hand-written and redacts the root, and
/// the root is zeroized on drop. The provider's own copy of the bytes is the
/// caller's responsibility to zeroize.
pub struct AuthorityEpochRoot {
    pub(crate) org: [u8; 16],
    pub(crate) version: [u8; 16],
    pub(crate) feed: [u8; 16],
    pub(crate) publisher_machine: [u8; 16],
    pub(crate) publisher: [u8; 16],
    pub(crate) server_generation: u64,
    pub(crate) epoch: u64,
    pub(crate) issued_ms: u64,
    pub(crate) expiry_ms: u64,
    pub(crate) root: Secret,
}

impl AuthorityEpochRoot {
    /// Assemble the context a provider returns. Validation happens in
    /// [`Publisher::from_authority`](crate::Publisher::from_authority): a
    /// provider cannot make a context valid by constructing it.
    ///
    /// `server_generation` is the authority's OWN monotonic generation for this
    /// identity, and `root` is the once-only CSPRNG root for
    /// `(org, version, publisher_machine, server_generation, epoch)`.
    #[allow(clippy::too_many_arguments)]
    #[must_use]
    pub fn new(
        org: [u8; 16],
        version: [u8; 16],
        feed: [u8; 16],
        publisher_machine: [u8; 16],
        publisher: [u8; 16],
        server_generation: u64,
        epoch: u64,
        issued_ms: u64,
        expiry_ms: u64,
        root: [u8; 32],
    ) -> Self {
        Self {
            org,
            version,
            feed,
            publisher_machine,
            publisher,
            server_generation,
            epoch,
            issued_ms,
            expiry_ms,
            root: Secret(root),
        }
    }

    /// The authority's monotonic generation for this identity.
    #[must_use]
    pub fn server_generation(&self) -> u64 {
        self.server_generation
    }

    /// The epoch this root is valid in.
    #[must_use]
    pub fn epoch(&self) -> u64 {
        self.epoch
    }

    /// When the authority issued it.
    #[must_use]
    pub fn issued_ms(&self) -> u64 {
        self.issued_ms
    }

    /// When it expires.
    #[must_use]
    pub fn expiry_ms(&self) -> u64 {
        self.expiry_ms
    }
}

fn hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(char::from_digit(u32::from(byte >> 4), 16).unwrap_or('0'));
        out.push(char::from_digit(u32::from(byte & 0x0f), 16).unwrap_or('0'));
    }
    out
}

impl std::fmt::Debug for AuthorityEpochRoot {
    /// Redacted on purpose: this type carries an epoch root, so it must never be
    /// printable into a log line.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("AuthorityEpochRoot")
            .field("org", &hex(&self.org))
            .field("version", &hex(&self.version))
            .field("feed", &hex(&self.feed))
            .field("publisher_machine", &hex(&self.publisher_machine))
            .field("publisher", &hex(&self.publisher))
            .field("server_generation", &self.server_generation)
            .field("epoch", &self.epoch)
            .field("issued_ms", &self.issued_ms)
            .field("expiry_ms", &self.expiry_ms)
            .field("root", &"<redacted 32-byte epoch root>")
            .finish()
    }
}

/// The injected trusted provider of current-epoch roots.
///
/// Contract for an implementation:
/// * return the CURRENT epoch root only — never a future epoch and never a
///   derived or prefetched key;
/// * generate the root once with a CSPRNG for
///   `(org, version, publisher_machine, server_generation, epoch)` and store it
///   encrypted at rest; a retry of the same scope returns the SAME root;
/// * assign `server_generation` monotonically for the identity, and bump it
///   whenever the authority cannot prove the publisher's durable counter state
///   is intact (see [`AuthorityRootGuard`]);
/// * never accept a caller-supplied root, and never log the root.
pub trait AuthorityRootProvider {
    /// Return the committed root for exactly this request, or fail.
    ///
    /// # Errors
    /// Returns an error when the scope is unknown, denied, or the authority
    /// cannot be reached; the caller fails closed.
    fn current_epoch_root(&self, request: &EpochRootRequest) -> Result<AuthorityEpochRoot>;
}

/// Per-process monotonicity and equivocation guard for authority roots.
///
/// The authority is create-once, but a wrong or compromised provider (or a
/// misconfigured deployment) could still hand the same identity a second root
/// for a scope it already used, or hand back an older generation. This guard
/// refuses both, so the publisher fails closed instead of emitting objects under
/// a key a peer already saw. Hold ONE instance for the process lifetime.
///
/// It stores only a SHA-256 fingerprint per scope, never key material.
#[derive(Default)]
pub struct AuthorityRootGuard {
    /// Highest generation accepted per (version, publisher).
    generations: BTreeMap<([u8; 16], [u8; 16]), u64>,
    /// Root fingerprint per scope: one root per scope, forever.
    roots: BTreeMap<RootScope, [u8; 32]>,
    /// Optional cross-host lease fence. [`None`] means the embedding runtime has
    /// not supplied an exclusive-lease fence, which is only acceptable for the
    /// local/test-only key path; a protected publisher must supply one.
    lease_fence: Option<Arc<dyn LeaseFence>>,
}

/// The scope one authority root covers, as the guard keys it.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct RootScope {
    version: [u8; 16],
    publisher: [u8; 16],
    epoch: u64,
    generation: u64,
}

impl AuthorityRootGuard {
    /// A fresh guard. One per process; a new process cannot detect a rolled-back
    /// journal locally, which is why the authority must issue a fresh generation.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// The highest generation this guard has accepted for the identity.
    #[must_use]
    pub fn observed_generation(&self, version: [u8; 16], publisher: [u8; 16]) -> Option<u64> {
        self.generations.get(&(version, publisher)).copied()
    }

    /// Attach the shared exclusive-lease fence. Consume the guard so a protected
    /// publisher cannot silently be built without it.
    #[must_use]
    pub fn with_lease_fence(mut self, fence: Arc<dyn LeaseFence>) -> Self {
        self.lease_fence = Some(fence);
        self
    }

    /// The attached lease fence, if any. [`Publisher::from_authority`]
    /// (crate::Publisher) takes it from here so the adopted root and the fence
    /// are always the same lease observation.
    #[must_use]
    pub fn lease_fence(&self) -> Option<&Arc<dyn LeaseFence>> {
        self.lease_fence.as_ref()
    }

    /// Check the context against everything this process has already accepted,
    /// then record it.
    ///
    /// * a generation below the observed one is a rollback -> [`Error::Replay`];
    /// * the same `(version, publisher, epoch, generation)` with a different root
    ///   is authority equivocation -> [`Error::Denied`];
    /// * the same scope with the same root is a legitimate retry -> accepted, so
    ///   the durable counter continues instead of restarting.
    pub(crate) fn accept(&mut self, context: &AuthorityEpochRoot) -> Result<()> {
        let identity = (context.version, context.publisher);
        if let Some(observed) = self.generations.get(&identity) {
            if context.server_generation < *observed {
                return Err(Error::Replay);
            }
        }
        let scope = RootScope {
            version: context.version,
            publisher: context.publisher,
            epoch: context.epoch,
            generation: context.server_generation,
        };
        let fingerprint: [u8; 32] = Sha256::digest(context.root.0).into();
        if let Some(previous) = self.roots.get(&scope) {
            if *previous != fingerprint {
                return Err(Error::Denied);
            }
        }
        let generation = context.server_generation;
        self.roots.insert(scope, fingerprint);
        self.generations.insert(identity, generation);
        Ok(())
    }
}
